macros.exemplo:
// A planilha está em `sheet`. Ctrl+Enter executa; Ctrl+Z desfaz a macro inteira.
// Todas as funções, com exemplos: botão "Guia".

// 1) Ler e escrever
sheet.set("F1", "Relatório");
sheet.log("A1 vale:", sheet.value("A1"));

// 2) Trabalhar com um intervalo
sheet.range("A1:D1").style({ bold: true });

// 3) Preencher com um laço
for (let linha = 2; linha <= 6; linha++) {
  sheet.set("F" + linha, "=D" + linha + "*0,1");
}

// 4) Criar uma função para usar nas células: =IMPOSTO(D2)
sheet.defineFunction("IMPOSTO", (valor) => valor * 0.15);

// 5) Ir para outra aba (bom para um botão de macro)
// sheet.goToSheet("Resumo");
